// Search for the documentation, in the box at the top of the nav. The sections in search-index.js (generated by
// createPages.xsl) are searched as you type: every term must start a word - in the page title, the section heading or
// its text - so 'break' finds 'breakpoints', 'group' finds 'current-group()' and 'xsl:it' finds 'xsl:iterate'.
// Keys: '/' to search, up and down to choose a result, Enter to go to it, Escape to close.
(function () {
	const input = document.getElementById('search-input');
	const index = window.SEARCH_INDEX;
	if (!input || !Array.isArray(index)) {
		return;
	}
	const maxResults = 12;
	const sections = index.map((entry) => ({
		...entry,
		pageLower: entry.page.toLowerCase(),
		sectionLower: entry.section.toLowerCase(),
		textLower: entry.text.toLowerCase()
	}));

	const panel = document.createElement('div');
	panel.id = 'search-results';
	panel.className = 'search-results';
	panel.setAttribute('role', 'listbox');
	panel.hidden = true;
	document.body.appendChild(panel);
	input.setAttribute('aria-controls', panel.id);
	input.setAttribute('aria-expanded', 'false');

	let results = [];
	let selected = -1;

	function escapeHtml(s) {
		return s.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
	}

	// a term, where it starts a word: not after a letter, digit or '_'
	function termPatterns(term) {
		const source = '(?<![\\p{L}\\p{N}_])' + term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
		return { one: new RegExp(source, 'u'), all: new RegExp(source, 'gu') };
	}

	function search(query) {
		const terms = query.toLowerCase().split(/\s+/).filter((term) => term !== '');
		const patterns = terms.map(termPatterns);
		const phrase = terms.length > 1 ? terms.join(' ') : null;
		const found = [];
		for (const section of sections) {
			let score = 0;
			const everyTerm = patterns.every((pattern) => {
				const inPage = pattern.one.test(section.pageLower);
				const inSection = pattern.one.test(section.sectionLower);
				const inText = (section.textLower.match(pattern.all) || []).length;
				// a match in the page title counts most for the page's introduction - not for each of its sections
				score += (inPage ? (section.section === '' ? 10 : 1) : 0) + (inSection ? 6 : 0) + Math.min(inText, 5);
				return inPage || inSection || inText > 0;
			});
			if (everyTerm) {
				if (phrase && (section.sectionLower.includes(phrase) || section.textLower.includes(phrase))) {
					score += 8;
				}
				// e.g. 'Breakpoints' for 'breakpoint', above sections that only mention breakpoints more
				if (section.sectionLower.startsWith(terms.join(' '))) {
					score += 5;
				}
				found.push({ section, score });
			}
		}
		found.sort((a, b) => b.score - a.score);
		return { patterns, results: found.slice(0, maxResults).map((f) => f.section) };
	}

	// the text, escaped, with each match of a term in <mark>
	function highlight(text, patterns) {
		const lower = text.toLowerCase();
		const ranges = [];
		for (const pattern of patterns) {
			for (const match of lower.matchAll(pattern.all)) {
				ranges.push([match.index, match.index + match[0].length]);
			}
		}
		ranges.sort((a, b) => a[0] - b[0]);
		let html = '';
		let at = 0;
		for (const [from, to] of ranges) {
			if (from >= at) {
				html += escapeHtml(text.slice(at, from)) + '<mark>' + escapeHtml(text.slice(from, to)) + '</mark>';
				at = to;
			}
		}
		return html + escapeHtml(text.slice(at));
	}

	// part of a section's text: around the first match, or its start
	function snippet(section, patterns) {
		const matches = patterns.map((pattern) => section.textLower.search(pattern.one)).filter((i) => i !== -1);
		const first = matches.length > 0 ? Math.min(...matches) : 0;
		const start = Math.max(0, first - 50);
		const end = Math.min(section.text.length, start + 160);
		return (start > 0 ? '…' : '') + highlight(section.text.slice(start, end), patterns) + (end < section.text.length ? '…' : '');
	}

	function render() {
		const query = input.value.trim();
		if (query === '') {
			close();
			return;
		}
		const found = search(query);
		results = found.results;
		if (results.length === 0) {
			panel.innerHTML = `<p class="search-empty">No results for <strong>${escapeHtml(query)}</strong></p>`;
		} else {
			panel.innerHTML = results.map((section, i) => `<a class="search-result" id="search-result-${i}" role="option" href="${escapeHtml(section.url)}">` +
				`<span class="search-result-title">${highlight(section.page, found.patterns)}` +
				(section.section ? ` › ${highlight(section.section, found.patterns)}` : '') + '</span>' +
				(section.text ? `<span class="search-result-text">${snippet(section, found.patterns)}</span>` : '') + '</a>').join('');
		}
		open();
		select(results.length > 0 ? 0 : -1);
	}

	function select(i) {
		selected = i;
		panel.querySelectorAll('.search-result').forEach((result, j) => result.setAttribute('aria-selected', String(j === i)));
		if (i >= 0) {
			input.setAttribute('aria-activedescendant', 'search-result-' + i);
			document.getElementById('search-result-' + i).scrollIntoView({ block: 'nearest' });
		} else {
			input.removeAttribute('aria-activedescendant');
		}
	}

	// below the search box - the panel is fixed, so it isn't clipped by the nav, and can be wider than it
	function place() {
		const box = input.getBoundingClientRect();
		const width = Math.min(480, window.innerWidth - 32);
		panel.style.top = (box.bottom + 6) + 'px';
		panel.style.left = Math.max(16, Math.min(box.left, window.innerWidth - width - 16)) + 'px';
		panel.style.width = width + 'px';
	}

	function open() {
		place();
		panel.hidden = false;
		input.setAttribute('aria-expanded', 'true');
	}

	function close() {
		panel.hidden = true;
		input.setAttribute('aria-expanded', 'false');
		input.removeAttribute('aria-activedescendant');
		selected = -1;
	}

	input.addEventListener('input', render);
	input.addEventListener('focus', render);
	input.addEventListener('keydown', (event) => {
		if ((event.key === 'ArrowDown' || event.key === 'ArrowUp') && results.length > 0 && !panel.hidden) {
			event.preventDefault();
			select((selected + (event.key === 'ArrowDown' ? 1 : -1) + results.length) % results.length);
		} else if (event.key === 'Enter' && selected >= 0 && !panel.hidden) {
			event.preventDefault();
			const url = results[selected].url;
			close();
			window.location.href = url;
		} else if (event.key === 'Escape') {
			if (panel.hidden) {
				input.blur();
			} else {
				close();
			}
		}
	});
	panel.addEventListener('mousemove', (event) => {
		const result = event.target.closest('.search-result');
		if (result) {
			select(Number(result.id.replace('search-result-', '')));
		}
	});
	panel.addEventListener('click', (event) => {
		if (event.target.closest('.search-result')) {
			close();
		}
	});
	document.addEventListener('mousedown', (event) => {
		if (!panel.hidden && !panel.contains(event.target) && event.target !== input) {
			close();
		}
	});
	document.addEventListener('keydown', (event) => {
		const active = document.activeElement;
		const typing = active && (/^(INPUT|TEXTAREA|SELECT)$/.test(active.tagName) || active.isContentEditable);
		if (event.key === '/' && !typing && !event.ctrlKey && !event.metaKey && !event.altKey) {
			event.preventDefault();
			input.focus();
			input.select();
		}
	});
	window.addEventListener('resize', () => !panel.hidden && place());
	window.addEventListener('scroll', () => !panel.hidden && place(), { passive: true });
})();
